from cloud_common import *  # noqa: F401,F403
R = 'f7-cloud'
T = []

# ---------------------------------------------------------------- 581 zones and static stability
T.append(topic(581, 'regions-zones-static-stability', R, 11, 'Regions, Zones and Static Stability',
 ['Explain regions and availability zones as nested fault domains',
  'Size capacity per zone so losing one zone does not overload the rest',
  'Design for static stability: survive a failure without calling the control plane'],
 2, 12, [328, 329],
 [text(581, 1, 'Fault domains nest: host, zone, region',
   'A cloud region is a geographic area that contains several availability zones. A zone is one or more data centres with its own power, cooling and network, a few kilometres or more from the others but linked to them with low-latency fibre. A failure usually stays inside one box: a host, a rack, a zone or, rarely, a whole region. Spreading replicas across zones turns a zone loss into a capacity problem instead of an outage.',
   ['fault-domains']),
  diagram(581, 2, 'What happens when a zone goes dark', 'The healthy zones must already hold enough capacity, because the first minutes are the hardest.', ['fault-domains', 'static-stability'],
   ['Instances in the failed zone stop answering health checks',
    'The load balancer stops sending them traffic, usually within seconds',
    'The surviving zones receive the whole load at once',
    'If they were sized for it, users see a short blip and nothing more',
    'Replacement capacity is added later, once the provider’s APIs are healthy']),
  text(581, 3, 'Worked example: three zones at 70% is not redundant',
   'A service needs 210 units of capacity at peak and runs 100 units in each of three zones, so each zone is 70% busy. Lose one zone and 210 units of load land on 200 units of capacity: 105%, overloaded. To survive, each zone needs 210 ÷ 2 = 105 units, which means running at 210 ÷ 315 ≈ 67% at peak. With four zones each needs only 210 ÷ 3 = 70 units, so the total spare drops from 50% to 33%.',
   ['zonal-capacity']),
  text(581, 4, 'Static stability: keep working without making changes',
   'A statically stable design survives a failure with what is already running. It does not need to launch instances, change DNS, push config or promote anything during the event. This matters because the control plane, the APIs that create and change resources, is more complex than the data plane that serves traffic, and it is often slow or throttled during the same large failure.',
   ['static-stability', 'control-plane-dependency']),
  text(581, 5, 'Trap: autoscaling will replace the lost zone',
   'Autoscaling reacts after the overload has begun. During a zone event every customer in the region asks for capacity at the same moment, launch APIs may be throttled, and each new instance still has to boot and warm up. Treat autoscaling as a way to restore spare capacity afterwards, not as the plan for surviving the first ten minutes.',
   ['static-stability', 'control-plane-dependency'])],
 [mc('t581-a1', 'fault-domains', 'What makes two availability zones useful as separate fault domains?',
   [('a', 'They sit in different countries, so one regulator or outage cannot touch both'),
    ('b', 'They have independent power, cooling and network, with low-latency links'),
    ('c', 'They run on different cloud providers, so a software bug cannot hit both'),
    ('d', 'They are in separate regions, so traffic between them costs nothing')], 'b',
   'Zones are in the same region, close enough for fast links but isolated in power, cooling and network. They are not in different countries or regions, they belong to one provider, and traffic between zones is often billed.'),
  mc('t581-a2', 'static-stability', 'Which design is statically stable against losing one zone?',
   [('a', 'Autoscaling launches replacements in the surviving zones when health checks fail'),
    ('b', 'A runbook tells on-call to update DNS and remove the failed zone’s addresses'),
    ('c', 'Each zone already runs enough capacity to absorb a lost zone’s share'),
    ('d', 'A standby region is started from the latest backups when a zone fails')], 'c',
   'Static stability means nothing has to change during the failure. Autoscaling and DNS edits both depend on control-plane calls and take time; restoring a standby region is a disaster-recovery plan for a much larger event.'),
  mc('t581-a3', 'control-plane-dependency', 'During a zone outage the provider’s API for launching instances is slow and throttled. Which recovery step is most at risk?',
   [('a', 'Load balancer health checks marking the failed zone’s instances down'),
    ('b', 'Launching replacement instances in the two healthy zones'),
    ('c', 'Instances already running in healthy zones serving requests'),
    ('d', 'Clients retrying a failed request against another healthy instance')], 'b',
   'Launching is a control-plane action. Health checks, already-running instances and client retries are all data-plane paths that keep working without the launch API.'),
  mc('t581-a4', 'fault-domains', 'Six app replicas are spread over three zones, but all of them use one database primary in zone A. What happens when zone A fails?',
   [('a', 'Two-thirds of the replicas keep serving, so about a third of requests fail'),
    ('b', 'Every replica loses its database until a primary is promoted elsewhere'),
    ('c', 'Requests keep working because replicas in zones B and C cache all reads'),
    ('d', 'The load balancer moves the database primary to zone B with the traffic')], 'b',
   'A single dependency in one zone makes the whole service zonal. The surviving app replicas are healthy but useless without a database; a load balancer does not move databases, and caches rarely hold everything.'),
  order('t581-a5', 'static-stability', 'Order what a statically stable service does when zone C fails.',
   ['Health checks for zone C’s instances start failing', 'The load balancer stops sending traffic to zone C',
    'Zones A and B carry the load with capacity already running', 'Spare capacity is rebuilt once launch APIs recover'],
   ['s3', 's1', 's4', 's2'], 'Detect, drain, absorb with what is running, and only then rebuild the spare.'),
  est('t581-a6', 'zonal-capacity', 'A service peaks at 240 units of load and runs in 4 zones. How many units must each zone hold so losing any one zone causes no overload?', 'units', 80,
   ['Load spreads evenly over the surviving zones', 'No autoscaling during the event'], '240 ÷ (4 − 1)', '240 ÷ 3 = 80 units per zone',
   'Sanity check: 4 × 80 = 320 units in total, about 33% more than the peak. Sizing at 240 ÷ 4 = 60 would overload the remaining three zones at 133%.', 0.05, [60, 120])],
 flash(581, [('Region vs zone?', 'A region is an area with several zones; a zone is isolated power, cooling and network with fast links to its neighbours.'),
             ('Capacity per zone to survive one zone loss?', 'Peak ÷ (zones − 1).'),
             ('Static stability?', 'Surviving a failure with what is already running, without control-plane calls such as launches or DNS changes.')]),
 src([('AWS Fault Isolation Boundaries: Static stability', 'https://docs.aws.amazon.com/whitepapers/latest/aws-fault-isolation-boundaries/static-stability.html'),
      ('AWS Fault Isolation Boundaries: Availability Zones', 'https://docs.aws.amazon.com/whitepapers/latest/aws-fault-isolation-boundaries/availability-zones.html'),
      ('Microsoft Learn: What are availability zones?', 'https://learn.microsoft.com/en-us/azure/reliability/availability-zones-overview'),
      ('Google Cloud: Design reliable infrastructure', 'https://cloud.google.com/architecture/infra-reliability-guide/design')]),
 deep(['fault-domains', 'zonal-capacity', 'static-stability', 'control-plane-dependency'], 'How zone failures are contained and survived',
  ['Providers build each zone with separate power feeds, cooling and network paths so that a fire, flood, power cut or bad network change in one zone does not take down its neighbours. Zones in a region are far enough apart to fail independently and close enough, usually a few milliseconds of round trip, to replicate data synchronously. Regions are much further apart and share far less, which is why cross-region replication is usually asynchronous.',
   'A service becomes zone-resilient only if every part of its request path is spread across zones: load balancers, app instances, caches, queues and the database. One component pinned to a single zone, such as a database primary with no standby, or a NAT gateway that every private subnet routes through, quietly makes the whole service as fragile as that zone.',
   'Capacity has to be spread too. With N zones and a peak load P, each zone must be able to carry P ÷ (N − 1) for the service to survive a zone loss without overload. The spare is then P ÷ (N − 1) in total, so it shrinks as zones are added: 50% extra for three zones, 33% for four. Check the other limits as well: connection pools, database replicas and per-zone quotas must also handle the extra share.',
   'Cloud systems split into a control plane, which creates, changes and deletes resources, and a data plane, which serves traffic on resources that already exist. Data planes are simpler and designed to keep running on their last known configuration. Control planes depend on more systems and are the first to struggle during a large event, when many customers call them at once.',
   'Static stability uses that difference. Pre-provision the capacity needed for a zone loss, keep health checks and load balancers removing bad targets on their own, and avoid recovery steps that need new resources or config changes. Autoscaling and replacement still matter, but they rebuild the spare capacity after the event instead of carrying the service through it.'],
  ['Any production service that must survive a zone failure without a visible outage.', 'Services whose recovery would otherwise depend on launching capacity during a regional event.'],
  ['Avoid paying for N − 1 sizing on dev and test environments where an outage is acceptable.', 'Avoid treating zones as a substitute for backups or for a second region; a bad deploy or deleted data hits every zone.'],
  ['Design', 'Zone loss', 'Cost'],
  [['3 zones sized for the peak only', 'Survivors overloaded at 150%', 'Lowest'],
   ['3 zones sized for N − 1', 'Absorbed with what is running', '50% spare'],
   ['4 zones sized for N − 1', 'Absorbed with what is running', '33% spare'],
   ['Rely on autoscaling', 'Overload until launches succeed', 'Low, but risky']],
  'Sizing a checkout service for one zone loss',
  ['Peak load of 210 units', 'Load spreads evenly across healthy zones', 'Illustrative numbers, not a real company’s'],
  ['Three zones sized for the peak: 70 units each; losing one puts 210 on 140, which is 150%.',
   'Three zones sized for N − 1: 210 ÷ 2 = 105 units each, 315 in total, so 67% busy at peak.',
   'Four zones sized for N − 1: 210 ÷ 3 = 70 units each, 280 in total, so 75% busy at peak.',
   'Moving from three zones to four cuts the spare from 105 units to 70 with the same protection.'],
  'Size each zone for peak ÷ (zones − 1); more zones make the insurance cheaper, if the region has them.',
  'Static stability in the AWS fault isolation guidance', 'Official documentation',
  'The AWS fault isolation boundaries whitepaper describes static stability as a workload continuing to operate during an impairment without needing to make changes. It recommends pre-provisioning enough capacity across Availability Zones that losing one does not require launching new resources, and explains that data planes are designed for higher availability than control planes. Microsoft and Google publish similar guidance on spreading workloads over zones.',
  [('“We have three zones, so we are redundant.”', '“Three zones help only if each holds peak ÷ 2, so a zone loss does not overload the other two.”'),
   ('“Autoscaling will replace the lost zone.”', '“I’d pre-provision for a zone loss and let autoscaling rebuild the spare afterwards, because launch APIs can be slow during the event.”')],
  ['Zones isolate power, cooling and network inside one region.', 'Every dependency in the request path needs to be spread, not just the app servers.', 'Hold peak ÷ (zones − 1) per zone to survive one zone loss.', 'Static stability means surviving on what is already running, without control-plane calls.']),
 predict('Three zones at 70%',
  'A service runs in three zones, each 70% busy at peak. Zone B loses power. Autoscaling adds instances when CPU passes 80%. What do users see in the first ten minutes?',
  [('a', 'Errors and slow pages: the two healthy zones are asked for 105% of what they can do',
    'Right: 3 × 70% of one zone’s capacity lands on two zones, 105% each, before any new instance is ready.'),
   ('b', 'Nothing: autoscaling adds the missing capacity before anyone notices',
    'Launches, boot and warm-up take minutes, and launch APIs can be throttled during a zone event.'),
   ('c', 'A short blip while the load balancer drains zone B, then normal service',
    'Draining is fast, but the remaining zones do not have enough capacity for the whole load.')], 'a',
  'Size each zone for the peak divided by the number of surviving zones: here no zone should be more than about 67% busy at peak. Autoscaling then restores spare capacity instead of being the plan.'),
 see([(56, 'Regional failover and disaster recovery go one fault domain further'), (55, 'How redundancy turns into availability numbers'), (328, 'Why autoscaling restores spare capacity rather than carrying a failure')])))

# ---------------------------------------------------------------- 582 cloud identities (refocused in review: policy design lives in Security 666)
T.append(topic(582, 'cloud-identities-roles-federation', R, 12, 'Cloud Identities: Roles, Federation and Short-Lived Credentials',
 ['Tell a role, which hands out expiring sessions, from a user with a long-lived key, and read a role’s trust and permission policies',
  'Trace how workload identity and OIDC federation turn a platform-signed token into short-lived cloud credentials',
  'Set up cross-account role assumption and predict which credential the SDK’s credential chain will pick'],
 2, 12, [325, 323],
 [text(582, 1, 'Users hold keys; roles hand out sessions',
   'A cloud user or a service-account key carries a long-lived secret that works until someone revokes it. A role has no secret of its own. A trusted caller assumes it and receives a session: a temporary key, secret and token that expire, typically after an hour. Every role therefore has two policies. The trust policy says who may assume it; the permission policy says what the session may do. On Google Cloud the same split appears as permission to impersonate a service account, and Azure uses managed identities and federated credentials.',
   ['roles-vs-users', 'trust-policy']),
  diagram(582, 2, 'Exchanging a CI token for cloud credentials', 'No key is stored anywhere; each run proves who it is and gets a session that dies with it.', ['federation', 'trust-policy'],
   ['The CI job asks its platform for a signed OIDC token for this run',
    'The token names the issuer, the audience and a subject such as repo, branch or environment',
    'The job sends the token to the cloud’s token service and names the role it wants',
    'The token service checks the signature against the issuer’s published keys',
    'The role’s trust policy checks the audience and the subject claim',
    'The job receives credentials that expire in about an hour and calls the cloud APIs']),
  text(582, 3, 'Worked example: deploying across accounts',
   'Pipelines run in a tooling account; production lives in its own account. The production account has a deploy role whose trust policy names the tooling account’s CI role. The CI role’s own permission policy allows it to call AssumeRole on exactly that deploy role. Both sides must agree: if either policy is missing, the call is denied. The CI job gets a one-hour production session, and production never holds a credential that belongs to the tooling account. When a third-party vendor assumes your role, also require an external ID so another of its customers cannot trick it into using yours.',
   ['cross-account']),
  text(582, 4, 'Trap: trusting the issuer instead of the repository',
   'GitHub Actions signs tokens for every repository on github.com with one issuer. A trust policy that checks only the issuer and the audience therefore accepts a workflow from anyone’s repository that asks for your role. GitHub’s and AWS’s guidance is to condition on the subject claim, such as repo:your-org/your-repo:environment:prod, and Google Cloud recommends an attribute condition on the organisation or repository for shared issuers like GitHub. The issuer proves the token is from GitHub, not that it is from you.',
   ['federation', 'trust-policy']),
  text(582, 5, 'The credential chain: which identity is your code using?',
   'Cloud SDKs look for credentials in a fixed order and stop at the first they find. A typical AWS order is environment variables, shared config and credentials files, a web identity token file, the container credentials endpoint and finally the instance metadata service; Google’s Application Default Credentials check a key-file variable, then local gcloud credentials, then the attached service account. The exact order varies by SDK. The trap: an old access key left in an environment variable silently wins over the workload identity you carefully scoped.',
   ['credential-chain'])],
 [mc('t582-a1', 'trust-policy', 'A deploy role trusts GitHub’s OIDC issuer and checks the audience claim, but not the subject. Who can assume it?',
   [('a', 'Only workflows in repositories owned by the role’s own organisation'),
    ('b', 'A workflow in any GitHub repository that requests a token for it'),
    ('c', 'Only workflows on the default branch of repositories you own'),
    ('d', 'Nobody, because the provider rejects roles with no subject condition')], 'b',
   'One issuer signs tokens for every GitHub repository, so without a subject condition any repository can assume the role. Nothing in the policy checks the organisation or the branch; those live in the subject claim, which is exactly what is missing. The cloud does not reject the policy, which is why GitHub and the providers warn you to add the condition.'),
  mc('t582-a2', 'cross-account', 'A CI role in account A calls AssumeRole on a deploy role in account B. B’s trust policy names A’s CI role, yet the call is denied. What is most likely missing?',
   [('a', 'A long-lived access key in account B for the CI role to sign with'),
    ('b', 'A network peering link between the two accounts’ private networks'),
    ('c', 'A copy of the CI role created inside account B with the same name'),
    ('d', 'A permission in the CI role’s own policy to assume B’s deploy role')], 'd',
   'Cross-account assumption needs both sides: B’s trust policy must name the caller, and the caller’s permission policy must allow AssumeRole on that role. No key is needed, because the session is the credential; role assumption is an API call, not network traffic between private networks; and duplicating the role in B adds nothing the trust policy does not already say.'),
  mc('t582-a3', 'federation', 'Why is federating CI to the cloud with signed identity tokens safer than storing an access key as a CI secret?',
   [('a', 'Identity tokens are encrypted, while access keys travel in plain text'),
    ('b', 'Each run gets credentials that expire soon and only one repo can get them'),
    ('c', 'Federated roles cannot be given more permissions than an access key'),
    ('d', 'The cloud provider skips its usual policy checks for federated callers')], 'b',
   'The gain is short life and narrow trust: credentials last about an hour and the trust policy only accepts tokens whose subject names the repository and branch or environment. Both methods travel over TLS, a federated role can be over-granted just like a key, and permission policies still apply to every call.'),
  mc('t582-a4', 'credential-chain', 'A pod’s workload identity can only write one bucket, yet its calls also reach other buckets and audit logs show a former engineer’s user. Why?',
   [('a', 'The workload identity inherits the permissions of whoever deployed it'),
    ('b', 'The metadata endpoint falls back to the account owner’s credentials'),
    ('c', 'An access key in its environment variables is found first by the SDK'),
    ('d', 'Audit logs record the user who created the pod, not the actual caller')], 'c',
   'SDKs take the first credentials in their chain, and environment variables come before the workload identity, so a leftover key silently wins. A workload identity does not inherit the deployer’s rights, the metadata endpoint never hands out the owner’s credentials, and audit logs record the principal that signed each call.'),
  order('t582-a5', 'federation', 'Order how a CI job turns its identity into cloud credentials.',
   ['The job requests a signed OIDC token from its CI platform', 'It sends the token to the cloud token service and names a role', 'The service verifies the signature with the issuer’s public keys', 'The role’s trust policy checks the audience and subject claims', 'Credentials that expire in about an hour are returned'],
   ['s4', 's2', 's5', 's1', 's3'], 'Token from the platform, exchange at the cloud, signature check, trust-policy check on the claims, then a short-lived session.'),
  tradeoff('t582-a6', 'workload-identity', 'A nightly job on a cloud VM must write reports to object storage.',
   ['Runs unattended', 'Only needs write access to one bucket', 'Security review bans long-lived keys'],
   [('p2', 'An access key saved in a config file on the VM', 'Static key'),
    ('p1', 'A workload identity attached to the VM, scoped to that bucket', 'Attached identity'),
    ('p3', 'An engineer’s personal credentials copied to the VM', 'Personal login')], 'p1',
   [('r3', 'A key in a config file is fine once the disk is encrypted'), ('r1', 'The platform rotates the VM’s credentials and they expire on their own'),
    ('r4', 'A personal login is easier to audit than a role'), ('r2', 'The SDK finds it through the metadata endpoint, so no secret is stored')],
   ['r1', 'r2'], ['r3', 'r4'],
   {'r3': 'Anyone with access to the running VM or a copy of its disk can still read the key.',
    'r4': 'Personal credentials mix the job’s actions with the engineer’s and break when they leave.'},
   'Attach an identity to the workload: the SDK picks it up from the metadata endpoint, and the platform issues and rotates short-lived credentials, so nothing secret sits on disk.')],
 flash(582, [('Trust policy vs permission policy?', 'Trust: who may assume the role. Permission: what the resulting session may do.'),
             ('Why condition on the OIDC subject claim?', 'Shared issuers such as GitHub sign tokens for every repository; the subject names your repo and branch or environment.'),
             ('Credential chain rule?', 'The SDK uses the first credentials it finds, so a stray key in an environment variable beats the workload identity.')]),
 src([('AWS IAM: Roles terms and concepts', 'https://docs.aws.amazon.com/IAM/latest/UserGuide/id_roles.html'),
      ('AWS IAM tutorial: Delegate access across accounts using roles', 'https://docs.aws.amazon.com/IAM/latest/UserGuide/tutorial_cross-account-with-roles.html'),
      ('GitHub Docs: Configuring OpenID Connect in Amazon Web Services', 'https://docs.github.com/en/actions/security-for-github-actions/security-hardening-your-deployments/configuring-openid-connect-in-amazon-web-services'),
      ('Google Cloud: Best practices for using Workload Identity Federation', 'https://cloud.google.com/iam/docs/best-practices-for-using-workload-identity-federation'),
      ('AWS SDKs and Tools: Standardized credential providers', 'https://docs.aws.amazon.com/sdkref/latest/guide/standardized-credentials.html')]),
 deep(['roles-vs-users', 'trust-policy', 'workload-identity', 'federation', 'cross-account', 'credential-chain'], 'How a workload gets a cloud identity',
  ['Every call to a cloud API is signed with credentials that identify a principal. Long-lived principals, such as a cloud user with an access key or a downloaded service-account key, carry a secret that works from anywhere until revoked. Roles carry no secret; callers assume them through the provider’s token service and receive a session that expires. Deciding what any principal may do is policy design, covered in the security track; this lesson is about how the identity is obtained.',
   'A role is guarded by its trust policy. It names the principals allowed to assume it: another role, an account, a cloud service such as the VM platform, or an external identity provider with conditions on the token’s claims. The permission policy then limits what the session can do. A session can be shortened, tagged with the caller’s details for audit, and narrowed further by a session policy when it is requested.',
   'Workload identity removes the secret from compute. A VM, container or function is attached to a role or service account, and the platform exposes short-lived credentials through a local metadata or credentials endpoint, refreshing them before they expire. In Kubernetes, a pod’s service account token can be exchanged for the cloud role mapped to it. Because the metadata endpoint hands credentials to anything that can reach it, protect it from request forgery, for example with session-token versions of the endpoint and hop limits.',
   'Federation extends the same idea to workloads outside the cloud. A CI platform, another cloud or an on-premises identity provider signs a token whose claims say who the workload is. The cloud verifies the signature against the issuer’s published keys, checks the audience, and lets the trust policy match the subject or other claims before issuing a session. For shared issuers, the subject condition is the only thing that separates your workflows from everyone else’s.',
   'Cross-account access is role assumption with two sides that must agree: the target role trusts the caller, and the caller is allowed to assume the target. Code finds its credentials through the SDK’s credential chain, which stops at the first source it finds, so environment variables, config files, web identity tokens, container endpoints and instance metadata are checked in a fixed order that varies by SDK. Knowing that order explains most “why is it using that identity?” incidents.'],
  ['Any workload that calls cloud APIs, including CI pipelines, scheduled jobs and pods.', 'Organisations with separate tooling and production accounts or projects.'],
  ['Avoid downloading service-account keys or creating cloud users for machines.', 'Avoid OIDC trust policies that check only the issuer and audience.'],
  ['Credential', 'Lifetime', 'Leak impact'],
  [['Long-lived access key', 'Until someone rotates it', 'Usable from anywhere until revoked'],
   ['Workload identity on a VM or pod', 'Minutes to hours, refreshed by the platform', 'Limited to its role and a short window'],
   ['Federated CI session', 'About one run', 'Tied to one repo, branch or environment and role']],
  'How long a leaked credential stays useful',
  ['A key or token is leaked in a public log', 'It takes the team 3 days to notice', 'Illustrative timings'],
  ['Long-lived key: usable for the full 3 days, 72 hours, and beyond until revoked.',
   'Federated credentials with a 1-hour lifetime: usable for at most 1 hour after they were issued.',
   '72 ÷ 1 = 72 times shorter exposure, before counting the narrower trust of the federated role.'],
  'Short lifetimes shrink exposure from “until noticed” to “at most one hour”.',
  'Provider guidance on federated CI', 'Official documentation',
  'GitHub’s guide to OpenID Connect with AWS tells you to define at least one condition so untrusted repositories cannot request your cloud credentials, and AWS recommends evaluating the subject claim in any role that trusts GitHub’s issuer. Google Cloud’s Workload Identity Federation best practices note that GitHub uses one issuer URL for all its tenants and recommend an attribute condition on the trusted organisation. AWS documents cross-account access as a trust policy on the target role plus permission for the caller to assume it.',
  [('“Our OIDC role checks the issuer, so only our CI can use it.”', '“I’d condition on the subject claim, our repo and environment, because that issuer signs tokens for every GitHub repository.”'),
   ('“We rotate the CI key every 90 days.”', '“I’d federate CI so each run gets credentials that expire in an hour, with no key stored at all.”')],
  ['A role has no secret; assuming it gives a session that expires.', 'Trust policy says who may assume a role; permission policy says what it can do.', 'Federated trust must check the subject, not just the issuer.', 'The SDK uses the first credentials in its chain; a stray key wins.']),
 predict('A role that trusts all of GitHub',
  'Your production deploy role trusts GitHub’s OIDC issuer with the audience sts.amazonaws.com and no other condition. A stranger finds the role’s name in your public workflow file and runs a workflow in their own repository that asks for it.',
  [('a', 'They receive deploy credentials for your production account',
    'Right: their token is genuinely signed by GitHub with the expected audience, which is all the policy checks.'),
   ('b', 'They are refused, because their token comes from another organisation',
    'Nothing in this trust policy looks at the organisation; that information is in the subject claim it ignores.'),
   ('c', 'They are refused, because they do not hold your account’s access key',
    'Federation needs no key; the signed token is the proof, which is why the trust conditions matter.')], 'a',
  'Add a subject condition such as repo:your-org/your-repo:environment:prod, protect that environment with review rules, and check the audit logs for sessions from unexpected repositories.'),
 see([(307, 'Where secrets live when a key cannot be avoided'), (309, 'Why CI credentials are a supply-chain target'), (685, 'Separate accounts, which cross-account roles connect'), (308, 'Request forgery against the metadata endpoint')])))
